                JsonSerializer.Serialize(writer, updateAddressRequest.Customs, jsonSerializerOptions);
            }
            if (updateAddressRequest.AddressTypesOption.IsSet)
            {
                writer.WritePropertyName("addressTypes");
                JsonSerializer.Serialize(writer, updateAddressRequest.AddressTypes, jsonSerializerOptions);
            }
            if (updateAddressRequest.BrandIdOption.IsSet)
                if (updateAddressRequest.BrandIdOption.Value != null)
                    writer.WriteString("brandId", updateAddressRequest.BrandId);
                else
                    writer.WriteNull("brandId");
        }
    }
}
